<?php $f=$usuarioEdit??['id'=>0,'nome'=>'','email'=>'','telefone'=>'','tipo'=>'usuario','ativo'=>1]; ?><div class="admin-page-title"><div><span class="eyebrow">CONTAS</span><h1><?= $f['id']?'Editar usuário':'Cadastrar usuário' ?></h1><p>Contas administrativas devem ser concedidas somente a pessoas autorizadas.</p></div><a class="btn btn-ghost" href="<?= h(url('admin/index.php?secao=usuarios')) ?>">← Voltar</a></div><form class="admin-card admin-form narrow-form" method="post" action="<?= h(url('admin/controllers/acao.php')) ?>"><?= csrf_field() ?><input type="hidden" name="acao" value="save_user"><input type="hidden" name="id" value="<?= (int)$f['id'] ?>"><input type="hidden" name="retorno" value="admin/index.php?secao=usuarios"><div class="form-grid"><label>Nome<input name="nome" required value="<?= h($f['nome']) ?>"></label><label>E-mail<input type="email" name="email" required value="<?= h($f['email']) ?>"></label><label>Telefone<input name="telefone" value="<?= h($f['telefone']) ?>"></label><label>Tipo de conta<input value="<?= $f['tipo']==='admin'?'Administrador':'Cliente' ?>" disabled><small>O perfil administrativo inicial é único e não pode ser concedido por este formulário.</small></label><label>Senha <?= $f['id']?'(preencha somente para redefinir)':'' ?><input type="password" name="senha" <?= $f['id']?'':'required minlength="8"' ?> minlength="8"></label><?php if($f['id']): ?><label>Situação<select name="ativo"><option value="1" <?= $f['ativo']?'selected':'' ?>>Ativo</option><option value="0" <?= !$f['ativo']?'selected':'' ?>>Desativado</option></select></label><?php endif; ?></div><button class="btn btn-red">Salvar usuário</button></form>
